"""Code parser: extract SCPI commands from C, C++, and Python source code."""

from __future__ import annotations
import re
from dataclasses import dataclass, field
from typing import List, Optional
import ast


@dataclass
class ParsedCommand:
    scpi_command: str
    line_number: int
    source_language: str
    context: str = ""       # surrounding code snippet
    is_query: bool = False
    variable_name: Optional[str] = None  # for query assignments


class CodeParser:
    """Extracts SCPI command strings from C, C++, or Python source code.

    Heuristic approach: looks for common VISA/SCPI library call patterns:
    - C/C++: viPrintf, viWrite, visa_write, scpi_send, send_command,
             viQueryf, viRead, ibwrt, ibrd, GPIB_write, etc.
    - Python: inst.write(), inst.query(), pyvisa write/query,
              visa.write(), rm.open_resource().write(), etc.
    """

    # Patterns for C/C++ SCPI writes
    C_WRITE_PATTERNS = [
        r'vi(?:Write|Printf)\s*\([^,]+,\s*"([^"]+)"',
        r'visa_write\s*\([^,]+,\s*"([^"]+)"',
        r'scpi_send\s*\([^,]+,\s*"([^"]+)"',
        r'send_command\s*\([^,)]*"([^"]+)"',
        r'ibwrt\s*\([^,]+,\s*"([^"]+)"',
        r'GPIB_write\s*\([^,]+,\s*"([^"]+)"',
        r'instrument_write\s*\([^,)]*"([^"]+)"',
        r'scpi_write\s*\([^,)]*"([^"]+)"',
        r'cmd_write\s*\([^,)]*"([^"]+)"',
        r'fprintf\s*\([^,]+,\s*"([^"]+)"',
        r'sprintf\s*\([^,]+,\s*"([^"]+)"',
        r'printf\s*\(\s*"([A-Z][A-Z0-9:*?][^"]*)"',  # Bare printf with SCPI-like string
    ]

    # Patterns for C/C++ SCPI queries
    C_QUERY_PATTERNS = [
        r'(?:(\w+)\s*=\s*)?vi(?:QueryF|Query)\s*\([^,]+,\s*"([^"]+)"',
        r'(?:(\w+)\s*=\s*)?visa_query\s*\([^,]+,\s*"([^"]+)"',
        r'(?:(\w+)\s*=\s*)?scpi_query\s*\([^,]+,\s*"([^"]+)"',
        r'(?:(\w+)\s*=\s*)?query_command\s*\([^,)]*"([^"]+)"',
    ]

    # Python write patterns
    PY_WRITE_PATTERNS = [
        r'(?:\w+)\.write\s*\(\s*[f\'"]([^\'"]+)[\'"]',
        r'(?:\w+)\.write\s*\(\s*f"([^"]+)"',
        r'send_scpi\s*\(\s*[\'"]([^\'"]+)[\'"]',
        r'scpi\s*\(\s*[\'"]([^\'"]+)[\'"]',
        r'instrument\.write\s*\(\s*[\'"]([^\'"]+)[\'"]',
    ]

    # Python query patterns
    PY_QUERY_PATTERNS = [
        r'(?:(\w+)\s*=\s*)?(?:\w+)\.query\s*\(\s*[\'"]([^\'"?]+\??)[\'"]',
        r'(?:(\w+)\s*=\s*)?(?:\w+)\.ask\s*\(\s*[\'"]([^\'"?]+\??)[\'"]',
        r'(?:(\w+)\s*=\s*)?query_scpi\s*\(\s*[\'"]([^\'"?]+\??)[\'"]',
    ]

    # SCPI-like string heuristic: starts with *IDN, *RST or WORD[:] pattern
    SCPI_HEURISTIC = re.compile(
        r'^(\*[A-Z]+|[A-Z][A-Z0-9_]+(?::[A-Z0-9_]+)*)[\s?]',
        re.IGNORECASE
    )

    def parse(self, code: str, language: str = "auto") -> List[ParsedCommand]:
        """Parse source code and return list of extracted SCPI commands."""
        if not code.strip():
            return []

        if language == "auto":
            language = self._detect_language(code)

        if language in ("c", "cpp", "c++"):
            return self._parse_c(code)
        elif language == "python":
            return self._parse_python(code)
        else:
            # Try both
            c_cmds = self._parse_c(code)
            py_cmds = self._parse_python(code)
            return c_cmds + py_cmds

    def _detect_language(self, code: str) -> str:
        if "#include" in code or "viWrite" in code or "ibwrt" in code:
            return "cpp"
        if "def " in code or "import " in code or ".write(" in code:
            return "python"
        if "::" in code or "std::" in code:
            return "cpp"
        return "auto"

    def _parse_c(self, code: str) -> List[ParsedCommand]:
        cmds: List[ParsedCommand] = []
        lines = code.split("\n")

        for lineno, line in enumerate(lines, 1):
            stripped = line.strip()
            if stripped.startswith("//") or stripped.startswith("/*"):
                continue

            # Queries first (order matters — queries have more groups)
            for pattern in self.C_QUERY_PATTERNS:
                for m in re.finditer(pattern, line, re.IGNORECASE):
                    var = m.group(1) if m.lastindex and m.lastindex >= 2 and m.group(1) else None
                    scpi = m.group(2) if m.lastindex and m.lastindex >= 2 else m.group(1)
                    if scpi and self._looks_like_scpi(scpi):
                        cmd_str = scpi.rstrip() + ("?" if not scpi.strip().endswith("?") else "")
                        cmds.append(ParsedCommand(
                            scpi_command=cmd_str,
                            line_number=lineno,
                            source_language="c",
                            context=stripped[:80],
                            is_query=True,
                            variable_name=var,
                        ))

            # Writes
            for pattern in self.C_WRITE_PATTERNS:
                for m in re.finditer(pattern, line, re.IGNORECASE):
                    scpi = m.group(1)
                    if scpi and self._looks_like_scpi(scpi):
                        is_q = scpi.strip().endswith("?")
                        cmds.append(ParsedCommand(
                            scpi_command=scpi.strip(),
                            line_number=lineno,
                            source_language="c",
                            context=stripped[:80],
                            is_query=is_q,
                        ))

        return self._deduplicate(cmds)

    def _parse_python(self, code: str) -> List[ParsedCommand]:
        cmds: List[ParsedCommand] = []
        lines = code.split("\n")

        for lineno, line in enumerate(lines, 1):
            stripped = line.strip()
            if stripped.startswith("#"):
                continue

            # Python queries
            for pattern in self.PY_QUERY_PATTERNS:
                for m in re.finditer(pattern, line, re.IGNORECASE):
                    if m.lastindex and m.lastindex >= 2:
                        var = m.group(1)
                        scpi = m.group(2)
                    else:
                        var = None
                        scpi = m.group(1)
                    if scpi and self._looks_like_scpi(scpi):
                        cmd_str = scpi.rstrip()
                        if not cmd_str.endswith("?"):
                            cmd_str += "?"
                        cmds.append(ParsedCommand(
                            scpi_command=cmd_str,
                            line_number=lineno,
                            source_language="python",
                            context=stripped[:80],
                            is_query=True,
                            variable_name=var,
                        ))

            # Python writes
            for pattern in self.PY_WRITE_PATTERNS:
                for m in re.finditer(pattern, line, re.IGNORECASE):
                    scpi = m.group(1)
                    if scpi and self._looks_like_scpi(scpi):
                        # Strip f-string format specifiers ({...})
                        scpi_clean = re.sub(r'\{[^}]*\}', '<VAR>', scpi).strip()
                        is_q = scpi_clean.endswith("?")
                        cmds.append(ParsedCommand(
                            scpi_command=scpi_clean,
                            line_number=lineno,
                            source_language="python",
                            context=stripped[:80],
                            is_query=is_q,
                        ))

        # Also try AST-based extraction for Python
        try:
            ast_cmds = self._parse_python_ast(code)
            cmds.extend(ast_cmds)
        except SyntaxError:
            pass

        return self._deduplicate(cmds)

    def _parse_python_ast(self, code: str) -> List[ParsedCommand]:
        """Use Python AST to find string literals that look like SCPI commands."""
        cmds: List[ParsedCommand] = []
        try:
            tree = ast.parse(code)
        except SyntaxError:
            return cmds

        for node in ast.walk(tree):
            if isinstance(node, ast.Constant) and isinstance(node.value, str):
                s = node.value.strip()
                if self._looks_like_scpi(s) and len(s) > 2:
                    lineno = getattr(node, 'lineno', 0)
                    is_q = s.endswith("?")
                    cmds.append(ParsedCommand(
                        scpi_command=s,
                        line_number=lineno,
                        source_language="python",
                        context="(AST string literal)",
                        is_query=is_q,
                    ))

        return cmds

    def _looks_like_scpi(self, s: str) -> bool:
        """Heuristic: does this string look like a SCPI command?"""
        s = s.strip()
        if not s or len(s) < 2:
            return False
        # Must start with * or uppercase word followed by : or space or ?
        return bool(self.SCPI_HEURISTIC.match(s + " "))

    @staticmethod
    def _deduplicate(cmds: List[ParsedCommand]) -> List[ParsedCommand]:
        seen = set()
        result = []
        for cmd in cmds:
            key = (cmd.scpi_command, cmd.line_number)
            if key not in seen:
                seen.add(key)
                result.append(cmd)
        return sorted(result, key=lambda c: c.line_number)

